#include <stdio.h>

int main(void) {
    int lo, hi;
    scanf("%d %d", &lo, &hi);
    int x;
    int attempts = 0;
    do {
        scanf("%d", &x);
        attempts++;
    } while (x < lo || x > hi);
    printf("%d %d\n", x, attempts);
    return 0;
}

