#include <stdio.h>

int main(void) {
    long long n;
    scanf("%lld", &n);
    do {
        long long sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        n = sum;
    } while (n >= 10);
    printf("%lld\n", n);
    return 0;
}

