#include <stdio.h>

int main(void) {
    int secret, guess;
    int tries = 0;
    scanf("%d", &secret);
    do {
        scanf("%d", &guess);
        tries++;
        if (secret > guess) {
            printf("больше\n");
        } else if (secret < guess) {
            printf("меньше\n");
        }
    } while (guess != secret);
    printf("угадано за %d\n", tries);
    return 0;
}

